70	+const sameText = (a: string, b: string): boolean =>
71	+  a.toLowerCase() === b.toLowerCase();
72	+
73	+// Case-insensitive; the canvas keys relation types by label, so one label maps to one complement.
74	+export const validateNewRelationType = ({
75	+  label: rawLabel,
76	+  complement: rawComplement,
77	+  sourceType,
78	+  destinationType,
79	+  relations,
80	+  shownLabels,
81	+  reservedNames,
82	+}: RelationType & {
83	+  sourceType: string;
84	+  destinationType: string;
85	+  relations: TripletFields[];
86	+  shownLabels: string[];
87	+  reservedNames: string[];
88	+}): string | null => {
89	+  const label = rawLabel.trim();
90	+  const complement = rawComplement.trim();
91	+  // "?" counts as missing, as everywhere else that reads relation types.
92	+  if (
93	+    !isRelationComplete({
94	+      label,
95	+      complement,
96	+      source: sourceType,
97	+      destination: destinationType,
98	+    })
99	+  )
100	+    return "Label and complement are required.";
101	+  // Lookups keyed by label read inherited Object properties as existing entries.
102	+  const prototypeName = [label, complement].find((n) => n in Object.prototype);
103	+  if (prototypeName) return `"${prototypeName}" is a reserved name.`;
104	+  // Queries can't tell the directions apart when both names match the same node type.
105	+  if (sourceType === destinationType && sameText(label, complement))
106	+    return "Label and complement must differ when both node types are the same.";
107	+
108	+  const shown = shownLabels.find(
109	+    (s) => sameText(s, label) || sameText(s, complement),
110	+  );
111	+  if (shown)
112	+    return `"${shown}" is already a relation between these node types.`;
113	+
114	+  const complete = relations.filter(isRelationComplete);
115	+  // createTripletForPair accepts an exact provisional match for this pair; only case twins are duplicates then.
116	+  const isAcceptedOnSave = complete.some(
117	+    (r) =>
118	+      !isAcceptedRelationSchema(r) &&
119	+      r.label === label &&
120	+      r.complement === complement &&
121	+      r.source === sourceType &&
122	+      r.destination === destinationType,
123	+  );
124	+  const duplicate = complete.find(
125	+    (r) =>
126	+      !(isAcceptedOnSave && r.label === label && r.complement === complement) &&
127	+      sameText(r.label, label) &&
128	+      sameText(r.complement, complement),
129	+  );
130	+  // The Add existing picker lists only accepted types.
131	+  if (duplicate)
132	+    return isAcceptedRelationSchema(duplicate)
133	+      ? `"${duplicate.label}" already exists. Use Add existing to add it for these node types.`
134	+      : `"${duplicate.label}" already exists as an imported relation type that has not been accepted yet.`;
135	+
136	+  const conflict = complete.find(
137	+    (r) => sameText(r.label, label) && !sameText(r.complement, complement),
138	+  );
139	+  if (conflict)
140	+    return `A relation called "${conflict.label}" already exists with complement "${conflict.complement}".`;
141	+
142	+  // Text reused across types shows the same label for one drag direction, and queries match both.
143	+  const others = complete.filter(
144	+    (r) => !(sameText(r.label, label) && sameText(r.complement, complement)),
145	+  );
146	+  const reverseHint = (r: TripletFields): string =>
147	+    isAcceptedRelationSchema(r)
148	+      ? " To add it the other way round, drag in the other direction and choose Add existing."
149	+      : "";
150	+  const labelAsComplement = others.find((r) => sameText(r.complement, label));
151	+  if (labelAsComplement)
152	+    return `"${labelAsComplement.complement}" is already the complement of "${labelAsComplement.label}".${reverseHint(labelAsComplement)}`;
153	+  const asLabel = others.find((r) => sameText(r.label, complement));
154	+  if (asLabel)
155	+    return `"${asLabel.label}" already exists as a relation.${reverseHint(asLabel)}`;
156	+  const asComplement = others.find((r) => sameText(r.complement, complement));
157	+  if (asComplement)
158	+    return `"${asComplement.complement}" is already the complement of "${asComplement.label}".`;
159	+
160	+  // Relation names register as query conditions and would replace a built-in one.
161	+  const reserved = reservedNames.find(
162	+    (n) => sameText(n, label) || sameText(n, complement),
163	+  );
164	+  if (reserved) return `"${reserved}" is a reserved query condition.`;
165	+
166	+  return null;
167	+};
