238	+    } finally {
239	+      // On success onClose unmounts the dialog, so only a failure resets the flag.
240	+      if (!saved) setIsSaving(false);
241	+    }
242	+    if (saved) onClose();
243	+  };
244	+
245	+  return (
246	+    <Dialog
247	+      isOpen
248	+      onClose={onClose}
249	+      canEscapeKeyClose={!isSaving}
250	+      canOutsideClickClose={!isSaving}
251	+      isCloseButtonShown={!isSaving}
252	+      title="Add relation type"
253	+      className="w-96"
254	+    >
255	+      <form
256	+        onSubmit={(e) => {
257	+          e.preventDefault();
258	+          void handleSubmit();
259	+        }}
260	+      >
261	+        <div className={Classes.DIALOG_BODY}>
262	+          <p className="text-gray-500">
263	+            {getNodeTypeText(pair.sourceType)} →{" "}
264	+            {getNodeTypeText(pair.targetType)}
265	+          </p>
266	+          <FormGroup label="Label" labelFor="dg-new-relation-label">
267	+            <InputGroup
268	+              id="dg-new-relation-label"
269	+              autoFocus
270	+              placeholder="e.g. supports"
271	+              value={label}
272	+              onChange={(e) => setLabel(e.target.value)}
273	+            />
274	+          </FormGroup>
275	+          <FormGroup label="Complement" labelFor="dg-new-relation-complement">
276	+            <InputGroup
277	+              id="dg-new-relation-complement"
278	+              placeholder="e.g. is supported by"
279	+              value={complement}
280	+              onChange={(e) => setComplement(e.target.value)}
281	+            />
282	+          </FormGroup>
283	+          {error && <div className="text-red-700">{error}</div>}
284	+        </div>
285	+        <div className={Classes.DIALOG_FOOTER}>
286	+          <div className={Classes.DIALOG_FOOTER_ACTIONS}>
287	+            <Button text="Cancel" onClick={onClose} disabled={isSaving} />
288	+            <Button
289	+              type="submit"
290	+              intent="primary"
291	+              text="Continue"
292	+              loading={isSaving}
293	+            />
294	+          </div>
295	+        </div>
296	+      </form>
297	+    </Dialog>
298	+  );
299	+};
